
-- 1. Total Records
SELECT COUNT(*) AS Total_Records
FROM supply_chain_data;

-- 2. Total Revenue
SELECT ROUND(SUM(`Revenue generated`),2) AS Total_Revenue
FROM supply_chain_data;

-- 3. Total Products Sold
SELECT SUM(`Number of products sold`) AS Total_Products_Sold
FROM supply_chain_data;

-- 4. Total Suppliers
SELECT COUNT(DISTINCT `Supplier name`) AS Total_Suppliers
FROM supply_chain_data;

-- 5. Product Categories
SELECT
    `Product type`,
    COUNT(*) AS Total_Products
FROM supply_chain_data
GROUP BY `Product type`
ORDER BY Total_Products DESC;

-- 6. Revenue Generated by Product Type
SELECT 
        `Product type`,
        ROUND(SUM(`Revenue generated`),2) as Total_Revenue
FROM supply_chain_data
GROUP BY `Product type`
ORDER BY Total_Revenue DESC;       

-- 7. Total Product sold by Product Type
SELECT 
      `Product type`,
      SUM(`Number of products sold`) AS Total_Product_Sold
FROM supply_chain_data
GROUP BY `Product type`
ORDER BY Total_Product_Sold DESC;

-- 8. Average Price By Product Type 
SELECT 
      `Product type`,
      ROUND(AVG(Price),2) AS AVG_Price
FROM supply_chain_data
GROUP BY `Product type`  
ORDER BY Avg_Price DESC;  

-- 9. Average Stock Level By Product Type 
SELECT 
     `Product type`,
     ROUND(AVG(`Stock levels`),2) AS Avg_Stock_Level
FROM supply_chain_data
GROUP BY `Product type`
ORDER BY Avg_Stock_Level DESC;    

-- 10. Top 10 Unique Products Revenue Generated
SELECT 
      SKU,
	 `Product type`,
	 `Revenue Generated` AS Revenue
FROM supply_chain_data
ORDER BY Revenue DESC
LIMIT 10;    

-- Supplier Analysis

-- 11. Highest Revenue Generated by supplier
SELECT
      `Supplier name`,
      ROUND(SUM(`Revenue generated`),2) AS Total_Revenue
 FROM supply_chain_data   
 GROUP BY `Supplier name`
 ORDER BY Total_Revenue DESC;
 
 -- 12. Most Products Sold By Suppliers
 SELECT 
       `Supplier name`,
       SUM(`Number of Products sold`) AS Tota_Product_Sold
FROM supply_chain_data 
GROUP BY `Supplier name`
ORDER BY Tota_Product_Sold DESC;     

-- 13.  Average Manufacturing Cost BY Suppliers 
SELECT 
      `Supplier name`,
      ROUND(AVG(`Manufacturing costs`),2) AS Avg_Manufaturing_Costs
FROM supply_chain_data 
GROUP BY `Supplier name`
ORDER BY AVG_Manufaturing_Costs DESC;    

-- 14. Average Defect By Suppliers
SELECT
      `Supplier name`,
      ROUND(AVG(`Defect rates`),2) AS Avg_Defect_Rates
FROM supply_chain_data 
GROUP BY `Supplier name`
ORDER BY Avg_Defect_Rates DESC;

-- 15. Supplier Performance Comparison
SELECT
    sp.Supplier_Name,
    sp.Cost_per_Unit_INR,
    sp.Lead_Time_Days,
    sp.Defect_Rate_Percent,
    ROUND(SUM(sc.`Revenue generated`),2) AS Revenue,
    SUM(sc.`Number of products sold`) AS Products_Sold
FROM Supplier_Performance sp
JOIN supply_chain_data sc
ON sp.Supplier_Name = sc.`Supplier name`
GROUP BY
    sp.Supplier_Name,
    sp.Cost_per_Unit_INR,
    sp.Lead_Time_Days,
    sp.Defect_Rate_Percent
ORDER BY Revenue DESC;
     
-- 16. Most Used Shipping Carriers
SELECT 
      `Shipping carriers`,
      COUNT(*) AS Total_Shippments
FROM supply_chain_data 
GROUP BY `Shipping carriers`      
ORDER BY Total_Shippments DESC ;     

-- 17. Average shipping cost by Carrier
SELECT
       `Shipping carriers`,
       ROUND(AVG(`Shipping Costs`),2) AS Avg_Shipping_Costs
FROM supply_chain_data
GROUP BY `Shipping carriers`      
ORDER BY Avg_Shipping_Costs DESC ;   

-- 18. Transportation Mode Analysis
SELECT
	`Transportation modes`,
    COUNT(*) AS Total_Shipment
FROM supply_chain_data
GROUP BY `Transportation modes`
ORDER BY Total_Shipment DESC ; 

-- 19. Highest Transportation Cost
SELECT 
	 `Transportation modes`,
     ROUND(AVG(`Costs`),2) AS Avg_Costs
FROM supply_chain_data
GROUP BY `Transportation modes`
ORDER BY Avg_Costs DESC;  

-- 20. Most expensive routes
SELECT
      `Routes`,
      ROUND(AVG(`Costs`),2) AS Avg_Route_Costs
FROM supply_chain_data 
GROUP BY `Routes`
ORDER BY Avg_Route_Costs DESC  ; 

-- 21. Longest Shipping Time by Carriers
SELECT 
      `Shipping carriers`,
      ROUND(AVG(`Shipping times`),2) AS Avg_Shipping_Time
FROM supply_chain_data 
GROUP BY `Shipping carriers`
ORDER BY Avg_Shipping_Time DESC;    

-- 22. Manufacturing cost by product type
SELECT 
      `Product type`,
      ROUND(AVG(`Manufacturing costs`),2) AS Avg_Manufacturing_Costs
FROM supply_chain_data  
GROUP BY `Product type`
ORDER BY Avg_Manufacturing_Costs DESC;    

-- 23. Production volume by Products Type
SELECT
    `Product type`,
    SUM(`Production volumes`) AS Total_Production
FROM supply_chain_data
GROUP BY `Product type`
ORDER BY Total_Production DESC;

-- 24. Average Lead Time by Product Type
SELECT
    `Product type`,
    ROUND(AVG(`Manufacturing lead time`),2) AS Avg_Manufacturing_Lead_Time
FROM supply_chain_data
GROUP BY `Product type`
ORDER BY Avg_Manufacturing_Lead_Time DESC;

-- 25. Inspection Result Distribution
SELECT
    `Inspection results`,
    COUNT(*) AS Total_Products
FROM supply_chain_data
GROUP BY `Inspection results`
ORDER BY Total_Products DESC;

-- 26. Average Defect Rates By Product Type
SELECT
    `Product type`,
    ROUND(AVG(`Defect rates`),2) AS Avg_Defect_Rate
FROM supply_chain_data
GROUP BY `Product type`
ORDER BY Avg_Defect_Rate DESC;

-- 27. Quality Performance By Inspection Results
SELECT
    `Inspection results`,
    ROUND(AVG(`Defect rates`),2) AS Avg_Defect_Rate,
    ROUND(AVG(`Manufacturing costs`),2) AS Avg_Manufacturing_Cost
FROM supply_chain_data
GROUP BY `Inspection results`
ORDER BY Avg_Defect_Rate DESC;

-- 28. TOP 10 Products at Highest Defect Rates
SELECT
    `SKU`,
    `Product type`,
    ROUND(`Defect rates`,2) AS Defect_Rate,
    `Inspection results`
FROM supply_chain_data
ORDER BY `Defect rates` DESC
LIMIT 10;

-- 29. Product with Higest Revenue but Low Stock
SELECT
    `SKU`,
    `Product type`,
    `Revenue generated`,
    `Stock levels`
FROM supply_chain_data
ORDER BY
    `Revenue generated` DESC,
    `Stock levels` ASC
LIMIT 10;
      
-- 30. The Product with HIghest Defect rate and also highest Manufacturing Rate
SELECT
    `SKU`,
    `Product type`,
    `Manufacturing costs`,
    `Defect rates`
FROM supply_chain_data
ORDER BY
    `Defect rates` DESC,
    `Manufacturing costs` DESC;     
    
-- 31. Shipping Carrier is expensive but slow 
SELECT
    `Shipping carriers`,
    ROUND(AVG(`Shipping costs`),2) AS Avg_Cost,
    ROUND(AVG(`Shipping times`),2) AS Avg_Time
FROM supply_chain_data
GROUP BY `Shipping carriers`
ORDER BY
    Avg_Cost DESC,
    Avg_Time DESC;    
    
-- 32. Transportation mode expenses is high but used less
SELECT
    `Transportation modes`,
    COUNT(*) AS Shipments,
    ROUND(AVG(`Costs`),2) AS Avg_Cost
FROM supply_chain_data
GROUP BY `Transportation modes`
ORDER BY Avg_Cost DESC, Shipments ASC;    

-- 33. The Product with High revenue and aslo high Defect Rate
SELECT
    `SKU`,
    `Product type`,
    `Revenue generated`,
    `Defect rates`
FROM supply_chain_data
ORDER BY
    `Revenue generated` DESC,
    `Defect rates` DESC;